// Fill in the integration's client ID and the URLs generated by the Raycast proxy.
export const oauthConfig = {
  clientId: "",
  authorizeUrl: "",
  tokenUrl: "",
  refreshTokenUrl: "",
};

export const oauthIsConfigured =
  Boolean(oauthConfig.clientId) &&
  [oauthConfig.authorizeUrl, oauthConfig.tokenUrl, oauthConfig.refreshTokenUrl || oauthConfig.tokenUrl].every(
    (url) => URL.canParse(url) && new URL(url).origin === "https://oauth.raycast.com",
  );
